import { ExtractionOutputSchema } from "@veryo/core";
import { z } from "zod";

/**
 * Gold label for one sample, stored next to it as `<sample>.expected.json`.
 * Drafts are generated by `pnpm eval:label` with `reviewed: false`; a human corrects the draft
 * and sets `reviewed: true`.
 */
export const GoldLabelSchema = z.object({
  source: z.string(),
  reviewed: z.boolean(),
  /** Whether a correct pipeline should send this document to the review queue. */
  expected_status: z.enum(["ok", "needs_review"]),
  output: ExtractionOutputSchema,
  /** Names and other personal data in the source that must never appear in the output. */
  pii_terms: z.array(z.string()),
  /** ISO receipt time passed to the extractor so it can infer a missing year. */
  received_at: z.string().optional(),
  notes: z.string().optional(),
});

export type GoldLabel = z.infer<typeof GoldLabelSchema>;
